/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: release, key, candidate, group, view, applied, summary, mount, ready
 *   Constants: uploads
 * Tests
 *   - rows that need no answer are folded, while values from file tags, an artist mismatch and Luna suggestions are flagged outside the fold
 *   - Publish stays unavailable while the server says it waits or needs answers, a placeholder-only credit says so at once, and otherwise it opens the confirmation
 *   - a conflict with the administrator's value offers Keep mine or Use lookup value bound to the saved value, and an append shows Album values as not applied
 *   - a tie lists the values that differ with each release's barcode, catalogue number, country and medium, and allows one release or none
 *   - the next step follows the lookup: a free retry first while busy or stopped, Luna first once unavailable or when nothing matches, and nothing while it runs or after it applied
 *   - the retry and the Luna next step act only on request, and Luna opens the Analyze confirmation with the project and daily budget
 *   - the Draft section's Analyze opens the same confirmation and starts nothing until it is confirmed
 *   - Luna suggestions arrive with the server's ticks: unticking is kept for the confirmation, a conflict cannot be ticked, and applying now accepts ticked and rejects unticked ones
 *   - the name box accepts names only, keeps no history and is not listener Search, and a folder-name run shows that name for editing
 *   - visibility defaults to public and changes in place as one field save
 *   - the summary polls while a lookup is queued, running or retrying, and a newer read refreshes the page's project
 *   - a lookup refusal shows its own message and reads the project and its summary again
 *   - Publish is not offered before the summary read settles or after it fails, nor once the publication is locked, which also fixes visibility
 *   - the status names an unconfigured, replaced or none-applied lookup and counts stale files, and the Luna step needs analysis access, budget and an idle analysis
 *   - answered conflicts fold with their answer, an artist mismatch is flagged only for a preselection applied in this run, and neither unsaved nor appended Album values are flagged as file tags
 *   - a suggestion whose value an unsaved change writes cannot be ticked, and the fold lists the shown tracks in approved order with decisions, cover and upload progress
 *   - the Analyze confirmation focuses Cancel, closes on Escape without starting anything, and cannot be confirmed while its budget is loading, failed or too small for one more run
 * @end-catalog */

import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { ImportSummary } from './ImportSummary';
import { ImportAnalysisControls } from './ImportDraftV2Editor';
import { ImportAnalysisConfirmation } from './ImportAnalysisConfirmation';
import { AdminMutation } from './useAdminMutation';
import { artistEntry, deferred, detail, json, labelEntry, lookupResponse, session, slotId, slotTwo, viewer } from './adminFixtures.testSupport';
import type { ImportDetail } from './adminApi';
import type { ImportUploadQueueView } from './useImportUploadQueue';
import { lunaTicksKey } from './importLunaTicks';
import { importSummaryQuery } from './importSummaryQuery';
import styles from './adminStyles';

/**
 * The Review and publish summary with its name box, candidate chooser and Analyze confirmation: what it folds and flags, the
 * Publish gate the server decides, conflict answers, the tie view, the next-step matrix, Luna ticks, the name box that keeps no
 * history, polling and the page refresh after a newer read. All names and identifiers are synthetic.
 */
const release = (n: number) => `0000000b-0000-4000-8000-00000000000${n}`;
const key = (n: number) => `musicbrainz:${release(n)}`;
const uploads = { running: false, current: null, files: {}, queue: {} } as unknown as ImportUploadQueueView;
const candidate = (n: number, extra: Record<string, unknown> = {}) => ({ key: key(n), releaseId: release(n), status: 'matching', title: `Synthetic Album ${n}`, artist: 'Synthetic Lead',
  label: `Label ${n}`, catalogNumber: `SYN-00${n}`, barcode: '4006381333931', country: n === 1 ? 'JP' : 'US', date: { year: 2021, month: 5, day: 1 }, formats: [n === 1 ? 'CD' : 'Digital Media'], trackCount: 2,
  comparison: { trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 1 }, differences: [], unknownLocalDurations: 0, unknownCandidateDurations: 0 }, groupKey: String(n).repeat(64), artistMismatch: false, ...extra });
const group = (n: number, title: string) => ({ groupKey: String(n).repeat(64), representativeKey: key(n), memberKeys: [key(n)], proposal: { albumTitle: title,
  artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: null }], label: `Label ${n}`, releaseDate: { year: 2020, month: null, day: null },
  tracks: [{ discNumber: 1, trackNumber: 1, title: 'First' }, { discNumber: 1, trackNumber: 2, title: 'Second' }] } });
const view = (extra: Record<string, unknown> = {}) => ({ run: 1, state: 'complete', issue: null, outcome: 'candidates', input: { trigger: 'tags', submitted: null }, candidates: [], groups: [],
  preselection: null, disclosure: null, applied: null, staleFiles: [], needsAnswer: { tie: false, conflicts: [] }, blocking: false, ...extra });
const applied = (extra: Record<string, unknown> = {}) => ({ run: 1, candidateKey: key(1), releaseId: release(1), choice: 'preselected', basis: 'onlyMatchingGroup', values: [], conflicts: [], flagged: [], ...extra });
const summary = (extra: Record<string, unknown> = {}) => ({ ...lookupResponse().summary, ...extra });

/** Renders the summary; `response` is the summary read's body, or a function answering it. */
function mount(item: ImportDetail = detail(), response: unknown = lookupResponse(), props: Partial<Parameters<typeof ImportSummary>[0]> = {}) {
  const fetch = vi.fn(async (path: string) => !path.endsWith('/lookup') ? json({ code: 'unexpected' }, 500) : typeof response === 'function' ? (response as () => Promise<Response>)() : json(response));
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const operation = new AdminMutation(), run = vi.spyOn(operation, 'run').mockImplementation(() => {}), onPublish = vi.fn();
  render(<QueryClientProvider client={client}><MemoryRouter><ImportSummary item={item} operation={operation} uploads={uploads} disabled={false} publishDisabled={false}
    approval={{ draft: item.draft, changes: [] }} onPublish={onPublish} {...props} /></MemoryRouter></QueryClientProvider>);
  return { run, onPublish, client, fetch, section: () => screen.getByRole('region', { name: 'Review and publish' }) };
}
const ready = () => screen.findByRole('button', { name: 'Review and approve publishing' });
beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); localStorage.clear(); sessionStorage.clear(); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('rows that need no answer are folded, while values from file tags, an artist mismatch and Luna suggestions are flagged outside the fold', async () => {
  const item = detail(); item.draft.album.title = 'Tag Title'; item.draft.album.artists = [artistEntry('Synthetic Lead')]; item.draft.tracks[0].title = 'Tag Song';
  item.automaticPaths = ['album.title', 'album.artists', `tracks.${slotId}.title`]; item.lookupPaths = ['album.artists'];
  const lookup = view({ candidates: [candidate(1)], groups: [group(1, 'Synthetic Album')], preselection: { candidateKey: key(1), basis: 'onlyMatchingGroup', artistMismatch: true }, applied: applied() });
  const { section } = mount(item, lookupResponse({ lookup, summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }, { id: 'd'.repeat(24), tick: 'resolved' }] }) }));
  await ready();
  const flagged = within(section()).getByRole('list', { name: 'Values to check' });
  expect(within(flagged).getAllByRole('listitem').map(item => item.textContent)).toEqual([
    'The applied release credits an artist that no artist tag of these files names. Check the Artist entries before publishing.',
    'Title: Tag Title · From file tags only', 'Track 1 · Title: Tag Song · From file tags only']);
  expect(flagged.closest('details')).toBeNull();
  // The ticked Luna suggestion stays outside the fold, labelled as Luna; the one equal to the current value resolved itself.
  const luna = within(section()).getByRole('group', { name: 'Luna suggestions' });
  expect(luna.closest('details')).toBeNull();
  expect(within(luna).getByRole('checkbox', { name: 'Title: Tag Title → Suggested Album · Suggested by Luna' })).toBeChecked();
  expect(within(luna).getAllByRole('checkbox')).toHaveLength(1);
  // The Artist entries rest on the applied release, so they are folded with every other row that needs no answer.
  const fold = within(section()).getByText('Values that need no answer').closest('details')!;
  expect(fold).not.toHaveAttribute('open');
  expect(within(fold).getByText('Synthetic Lead · Primary')).toBeInTheDocument();
  expect(within(fold).queryByText('Tag Title')).not.toBeInTheDocument();
  expect(within(fold).getByText('0 of 2 files confirmed')).toBeInTheDocument();
  expect(within(section()).getByText('Applied release: Synthetic Album 1')).toBeInTheDocument();
});

test('Publish stays unavailable while the server says it waits or needs answers, a placeholder-only credit says so at once, and otherwise it opens the confirmation', async () => {
  const conflicts = [{ path: 'album.label', slotId: null, lookup: labelEntry('Lookup Label'), answer: null }];
  let rendered = mount(detail(), lookupResponse({ summary: summary({ waiting: { uploads: true, lookup: true, analysis: true } }) }));
  expect(await ready()).toBeDisabled();
  for (const text of ['Publish waits until every selected file is uploaded and confirmed.', 'Publish waits while metadata lookup runs or retries automatically.', 'Publish waits while Luna analysis runs.'])
    expect(within(rendered.section()).getByText(text)).toHaveAttribute('role', 'status');
  cleanup();
  const item = detail(); item.draft.album.label = labelEntry('Mine');
  rendered = mount(item, lookupResponse({ lookup: view({ applied: applied({ conflicts }), needsAnswer: { tie: false, conflicts: ['album.label'] } }) }));
  expect(await ready()).toBeDisabled(); expect(screen.getByText('Answers needed before publishing: 1')).toBeInTheDocument();
  cleanup();
  rendered = mount(detail(), lookupResponse({ summary: summary({ placeholderOnly: true }) }));
  expect(await ready()).toBeDisabled();
  expect(screen.getByText(/credit only a placeholder such as Various Artists, so this import cannot be published yet/)).toBeInTheDocument();
  cleanup();
  // Publish includes unsaved changes, so an unsaved primary Artist entry lifts the placeholder-only hold at once.
  const credited = detail(), entries = [artistEntry('Synthetic Lead')];
  mount(credited, lookupResponse({ summary: summary({ placeholderOnly: true }) }), { approval: { draft: { ...credited.draft, album: { ...credited.draft.album, artists: entries } }, changes: [{ path: 'album.artists', base: [], value: entries }] } });
  expect(await ready()).toBeEnabled(); expect(screen.queryByText(/credit only a placeholder/)).not.toBeInTheDocument();
  cleanup();
  // Identity rows the server counts as unanswered are answered in Review, and this browser's own running uploads hold Publish too.
  mount(detail(), lookupResponse({ summary: summary({ identityAnswers: 2 }) }));
  expect(await ready()).toBeDisabled();
  expect(screen.getByText('Answers needed before publishing: 2')).toBeInTheDocument(); expect(screen.getByText('Records to choose in Review, existing or new: 2')).toBeInTheDocument();
  cleanup();
  mount(detail(), lookupResponse(), { uploads: { ...uploads, running: true } });
  expect(await ready()).toBeDisabled(); expect(screen.getByText('Publish waits until every selected file is uploaded and confirmed.')).toHaveAttribute('role', 'status');
  cleanup();
  rendered = mount(detail(), lookupResponse(), { publishDisabled: true });
  expect(await ready()).toBeDisabled();
  cleanup();
  rendered = mount();
  fireEvent.click(await ready()); expect(rendered.onPublish).toHaveBeenCalledOnce();
});

test('a conflict with the administrator\'s value offers Keep mine or Use lookup value bound to the saved value, and an append shows Album values as not applied', async () => {
  const item = detail(); item.draft.album.label = labelEntry('Mine'); item.draft.tracks[1].trackNumber = 7; item.revision = 4;
  const conflicts = [{ path: 'album.label', slotId: null, lookup: labelEntry('Lookup Label'), answer: null }, { path: `tracks.${slotTwo}.trackNumber`, slotId: slotTwo, lookup: 2, answer: null }];
  const { run, section } = mount(item, lookupResponse({ lookup: view({ applied: applied({ conflicts }), needsAnswer: { tie: false, conflicts: ['album.label', `tracks.${slotTwo}.trackNumber`] } }) }));
  const rows = within(await within(section()).findByRole('region', { name: 'Lookup values that differ from yours' })).getAllByRole('listitem');
  expect(rows.map(row => row.querySelector('strong')!.textContent)).toEqual(['Label', 'Track 2 · Track number']);
  expect(within(rows[0]).getByText('Mine')).toBeInTheDocument(); expect(within(rows[0]).getByText('Lookup Label')).toBeInTheDocument();
  const keep = within(rows[0]).getByRole('button', { name: 'Keep mine' });
  expect(keep).toHaveAccessibleDescription('Label');
  fireEvent.click(keep);
  fireEvent.click(within(rows[1]).getByRole('button', { name: 'Use lookup value' }));
  expect(run.mock.calls).toEqual([
    [`/${item.id}/lookup/resolve`, 'POST', { expectedRevision: 4, run: 1, candidateKey: key(1), answers: [{ path: 'album.label', answer: 'mine', base: { name: 'Mine', musicBrainzId: null } }] }],
    [`/${item.id}/lookup/resolve`, 'POST', { expectedRevision: 4, run: 1, candidateKey: key(1), answers: [{ path: `tracks.${slotTwo}.trackNumber`, answer: 'lookup', base: 7 }] }]]);
  cleanup();
  // An append applies no Album value: the server needs no answer for the label conflict, which shows as not applied.
  mount(item, lookupResponse({ summary: summary({ append: true }), lookup: view({ applied: applied({ conflicts }), needsAnswer: { tie: false, conflicts: [`tracks.${slotTwo}.trackNumber`] } }) }));
  await ready();
  expect(screen.getByText('Lookup Label · Not applied')).toBeInTheDocument();
  expect(screen.getByText('Mine · Not applied')).toBeInTheDocument();
  expect(screen.getByRole('combobox', { name: 'Visibility' })).toBeDisabled();
  expect(within(screen.getByRole('region', { name: 'Lookup values that differ from yours' })).getAllByRole('listitem')).toHaveLength(1);
  cleanup();
  // An append applies no Album value, so a Luna suggestion for one says so; a track suggestion is applied as usual.
  mount(item, lookupResponse({ summary: summary({ append: true, luna: [{ id: 'c'.repeat(24), tick: 'ticked' }, { id: 'd'.repeat(24), tick: 'unticked' }] }) }));
  const luna = await screen.findByRole('group', { name: 'Luna suggestions' });
  expect(within(luna).getAllByRole('checkbox').map(box => box.parentElement!.textContent)).toEqual(['Title: — → Suggested Album · Suggested by Luna · Not applied', 'Track 1 · Track number: — → 1 · Suggested by Luna']);
});

test('a tie lists the values that differ with each release\'s barcode, catalogue number, country and medium, and allows one release or none', async () => {
  const lookup = view({ candidates: [candidate(1), candidate(2)], groups: [group(1, 'Synthetic Album'), group(2, 'Synthetic Album (Deluxe)')], needsAnswer: { tie: true, conflicts: [] } });
  const { run, section } = mount(detail(), lookupResponse({ lookup }));
  const tie = await within(section()).findByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  const [first, second] = within(tie).getAllByRole('listitem');
  // Only the title and label differ; the shared Artist entries, date and tracks are not repeated.
  expect([...first.querySelectorAll('dt')].map(term => term.textContent)).toEqual(['Title', 'Label', 'Barcode', 'Catalogue number', 'Country', 'Medium']);
  expect([...second.querySelectorAll('dd')].map(value => value.textContent)).toEqual(['Synthetic Album (Deluxe)', 'Label 2', '4006381333931', 'SYN-002', 'US', 'Digital Media']);
  expect(await ready()).toBeDisabled(); expect(screen.getByText('Answers needed before publishing: 1')).toBeInTheDocument();
  fireEvent.click(within(second).getByRole('button', { name: 'Use this release' }));
  fireEvent.click(within(tie).getByRole('button', { name: 'Use none of these' }));
  // Every release also stays selectable in the folded list beside the tie, which offers none only once.
  const all = screen.getByText('Releases found: 2').closest('details')!;
  expect(within(all).getAllByRole('button', { name: 'Use this release' })).toHaveLength(2);
  expect(screen.getAllByRole('button', { name: 'Use none of these' })).toHaveLength(1);
  fireEvent.click(within(all).getAllByRole('button', { name: 'Use this release' })[0]);
  expect(run.mock.calls.map(call => call[2])).toEqual([{ expectedRevision: 1, run: 1, candidateKey: key(2) }, { expectedRevision: 1, run: 1, candidateKey: null }, { expectedRevision: 1, run: 1, candidateKey: key(1) }]);
  cleanup();
  // Without a tie every release stays selectable in a fold, and one that does not match says how it differs.
  const differing = candidate(2, { status: 'notMatching', groupKey: null, comparison: { trackCount: { local: 2, candidate: 3 }, discCount: { local: null, candidate: 1 }, differences: ['trackCount'], unknownLocalDurations: 0, unknownCandidateDurations: 0 } });
  mount(detail(), lookupResponse({ lookup: view({ candidates: [candidate(1), differing], groups: [group(1, 'Synthetic Album')], applied: applied() }) }));
  const fold = (await screen.findByText('Releases found: 2')).closest('details')!;
  expect(fold).not.toHaveAttribute('open');
  expect(within(fold).getByText('Tracks: 2 here, 3 on the release')).toBeInTheDocument();
  expect(within(fold).getByRole('button', { name: 'Applied' })).toBeDisabled();
  expect(within(fold).getByRole('button', { name: 'Use this release' })).toBeEnabled();
});

test('the next step follows the lookup: a free retry first while busy or stopped, Luna first once unavailable or when nothing matches, and nothing while it runs or after it applied', async () => {
  const cases: [Record<string, unknown> | null, string, string[], Record<string, unknown>?][] = [
    [null, 'Metadata lookup has not run yet. It runs once every selected file is uploaded, or look up a name below.', [], { waiting: { uploads: true, lookup: false, analysis: false } }],
    // Every needed file is uploaded yet no run exists (its automatic trigger failed): Luna is the next step beside the name box.
    [null, 'Metadata lookup has not run for these files. Look up a name below, or analyze with Luna.', ['Analyze with Luna']],
    [{ state: 'running', outcome: null }, 'Looking up metadata in MusicBrainz…', []],
    [{ state: 'retrying', outcome: null, issue: 'sourceBusy' }, 'MusicBrainz is busy or unavailable, so lookup retries automatically. You can retry now at no cost.', ['Retry lookup', 'Analyze with Luna']],
    [{ state: 'unavailable', outcome: null, issue: 'sourceUnavailable' }, 'Metadata lookup is unavailable. Analyze with Luna, or retry the lookup at no cost.', ['Analyze with Luna', 'Retry lookup']],
    [{ state: 'stopped', outcome: null, issue: 'grantExpired' }, 'Metadata lookup stopped because its administrator permission ended or its time ran out. Retry it, or analyze with Luna.', ['Retry lookup', 'Analyze with Luna']],
    [{ outcome: 'noRelease' }, 'No release was found. Try another name, or analyze with Luna.', ['Analyze with Luna']],
    [{ outcome: 'noQuery' }, 'There is nothing to look up: the files have no usable tags or folder name. Enter an Album or song name, or analyze with Luna.', ['Analyze with Luna']],
    [{ candidates: [candidate(1, { status: 'notMatching', groupKey: null })] }, 'No release matches these files. You can still choose one below, try another name, or analyze with Luna.', ['Analyze with Luna']],
    // Choosing none where nothing matched still leaves Luna as the next step.
    [{ candidates: [candidate(1, { status: 'notMatching', groupKey: null })], applied: applied({ candidateKey: null, releaseId: null, choice: 'none', basis: null }) }, 'No release is applied. Values from file tags are kept.', ['Analyze with Luna']],
    // Releases whose details could not be fetched are no proof that nothing matches: a free retry first, Luna beside it.
    [{ candidates: [candidate(1, { status: 'incomplete', groupKey: null, comparison: null }), candidate(2, { status: 'notMatching', groupKey: null })] },
      'Release details could not be fetched, so no match was confirmed. Retry the lookup at no cost, or analyze with Luna.', ['Retry lookup', 'Analyze with Luna']],
    [{ candidates: [candidate(1)], groups: [group(1, 'Synthetic Album')], applied: applied() }, 'Applied release: Synthetic Album 1', []]
  ];
  for (const [lookup, status, steps, extra] of cases) {
    const { section } = mount(detail(), lookupResponse({ lookup: lookup && view(lookup), summary: summary(extra) }));
    expect(await within(section()).findByText(status)).toHaveAttribute('role', 'status');
    const buttons = within(section()).queryAllByRole('button', { name: /^(Retry lookup|Analyze with Luna)$/ });
    expect(buttons.map(button => button.textContent)).toEqual(steps);
    // The next step is the primary action; the other is beside it.
    buttons.forEach((button, index) => expect(button.className.includes(styles.primary)).toBe(index === 0));
    cleanup();
  }
});

test('the retry and the Luna next step act only on request, and Luna opens the Analyze confirmation with the project and daily budget', async () => {
  const { run, section } = mount(detail(), lookupResponse({ lookup: view({ state: 'unavailable', outcome: null, issue: 'sourceUnavailable' }), summary: summary({ analysis: { runs: 1, attempts: 20, daily: 200 } }) }));
  fireEvent.click(await within(section()).findByRole('button', { name: 'Retry lookup' }));
  expect(run).toHaveBeenLastCalledWith(`/${detail().id}/lookup/retry`, 'POST', { expectedRevision: 1 });
  fireEvent.click(within(section()).getByRole('button', { name: 'Analyze with Luna' }));
  const dialog = await screen.findByRole('dialog', { name: 'Analyze with Luna?' });
  expect(within(dialog).getByText('Left for this import: 1 analyses and 20 AI calls.')).toBeInTheDocument();
  expect(within(dialog).getByText('Left today for all imports: 200 AI calls.')).toBeInTheDocument();
  expect(run).toHaveBeenCalledTimes(1);
  fireEvent.click(within(dialog).getByRole('button', { name: 'Start Luna analysis' }));
  expect(run).toHaveBeenLastCalledWith(`/${detail().id}/analyze`, 'POST', { expectedRevision: 1 });
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  cleanup();
  // A budget too small for one more run (one call for the Album and one per ten files) cannot be confirmed.
  mount(detail(), lookupResponse({ lookup: view({ outcome: 'noRelease' }), summary: summary({ analysis: { runs: 1, attempts: 20, daily: 1 } }) }));
  fireEvent.click(await screen.findByRole('button', { name: 'Analyze with Luna' }));
  expect(within(await screen.findByRole('dialog')).getByRole('button', { name: 'Start Luna analysis' })).toBeDisabled();
});

test('the Draft section\'s Analyze opens the same confirmation and starts nothing until it is confirmed', async () => {
  const item = detail(); item.analysis = { ...item.analysis, generation: 0, state: 'idle' };
  vi.stubGlobal('fetch', vi.fn(async () => json(lookupResponse())));
  const client = new QueryClient(); client.setQueryData(['browser-session'], session); const onAction = vi.fn();
  render(<QueryClientProvider client={client}><ImportAnalysisControls item={item} available active={false} startDisabled={false} stopDisabled={false} onAction={onAction} /></QueryClientProvider>);
  fireEvent.click(screen.getByRole('button', { name: 'Analyze' }));
  const dialog = await screen.findByRole('dialog', { name: 'Analyze with Luna?' });
  fireEvent.click(within(dialog).getByRole('button', { name: 'Cancel' })); expect(onAction).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Analyze' }));
  const start = within(await screen.findByRole('dialog')).getByRole('button', { name: 'Start Luna analysis' });
  await waitFor(() => expect(start).toBeEnabled()); fireEvent.click(start);
  expect(onAction).toHaveBeenCalledWith('analyze');
});

test('Luna suggestions arrive with the server\'s ticks: unticking is kept for the confirmation, a conflict cannot be ticked, and applying now accepts ticked and rejects unticked ones', async () => {
  const item = detail(); item.draft.tracks[0].trackNumber = 9;
  const { run, section } = mount(item, lookupResponse({ summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }, { id: 'd'.repeat(24), tick: 'conflict' }] }) }));
  const luna = await within(section()).findByRole('group', { name: 'Luna suggestions' });
  const [title, number] = within(luna).getAllByRole<HTMLInputElement>('checkbox');
  expect([title.checked, number.checked, number.disabled]).toEqual([true, false, true]);
  expect(within(luna).getByText('This value changed after analysis. Edit the draft manually or keep its current value.')).toBeInTheDocument();
  fireEvent.click(title);
  expect(title).not.toBeChecked(); expect(adminWorkspace.buffer(lunaTicksKey(item.id))).toEqual({ ['c'.repeat(24)]: false });
  fireEvent.click(title);
  fireEvent.click(within(luna).getByRole('button', { name: 'Apply ticked suggestions now' }));
  expect(run).toHaveBeenLastCalledWith(`/${item.id}/adopt`, 'POST', { expectedRevision: 1, generation: 1, selectedIds: ['c'.repeat(24)], rejectIds: ['d'.repeat(24)] });
});

