test('visibility defaults to public and changes in place as one field save', async () => {
  const item = detail(); item.revision = 3;
  const { run } = mount(item);
  const visibility = await screen.findByRole('combobox', { name: 'Visibility' });
  expect(visibility).toHaveValue('public');
  fireEvent.change(visibility, { target: { value: 'hidden' } });
  expect(run).toHaveBeenCalledWith(`/${item.id}`, 'PATCH', { expectedRevision: 3, changes: [{ path: 'album.visibility', base: 'public', value: 'hidden' }] });
});

test('the summary polls while a lookup is queued, running or retrying, and a newer read refreshes the page\'s project', async () => {
  const access = { viewerId: viewer, epoch: 0, generation: 1 }, interval = (state: string | null, online = true) =>
    importSummaryQuery(access, detail(), online).refetchInterval({ state: { data: state ? lookupResponse({ lookup: view({ state }) }) as never : undefined } });
  expect([interval('queued'), interval('running'), interval('retrying'), interval('complete'), interval('unavailable'), interval(null), interval('running', false)])
    .toEqual([3000, 3000, 10_000, false, false, false, false]);
  const { client } = mount(detail(), lookupResponse({ revision: 2, valueRevision: 1 }));
  const invalidate = vi.spyOn(client, 'invalidateQueries');
  await waitFor(() => expect(invalidate).toHaveBeenCalledWith({ queryKey: ['admin-imports', viewer, expect.any(Number), expect.any(Number), detail().id], exact: true }));
});

test('a lookup refusal shows its own message and reads the project and its summary again', async () => {
  const item = detail(), lookup = view({ candidates: [candidate(1), candidate(2)], groups: [group(1, 'A'), group(2, 'B')], needsAnswer: { tie: true, conflicts: [] } });
  vi.stubGlobal('fetch', vi.fn(async (path: string, init?: RequestInit) => init?.method === 'POST' ? json({ code: 'ADMIN_IMPORT_LOOKUP_STALE' }, 409) : json(lookupResponse({ lookup }))));
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const operation = new AdminMutation(), invalidate = vi.spyOn(client, 'invalidateQueries');
  render(<QueryClientProvider client={client}><MemoryRouter><ImportSummary item={item} operation={operation} uploads={uploads} disabled={false} publishDisabled={false} approval={{ draft: item.draft, changes: [] }} onPublish={() => {}} /></MemoryRouter></QueryClientProvider>);
  fireEvent.click(await screen.findByRole('button', { name: 'Use none of these' }));
  await waitFor(() => expect(operation.getSnapshot().error).toBe('lookup_stale'));
  expect(invalidate).toHaveBeenCalledWith({ queryKey: ['admin-imports', viewer, expect.any(Number), expect.any(Number), item.id] });
});

test('Publish is not offered before the summary read settles or after it fails, nor once the publication is locked, which also fixes visibility', async () => {
  const read = deferred<Response>();
  let rendered = mount(detail(), () => read.promise);
  expect(within(rendered.section()).getByRole('status')).toHaveTextContent('Loading…');
  expect(screen.queryByRole('button', { name: 'Review and approve publishing' })).not.toBeInTheDocument();
  read.resolve(json(lookupResponse())); expect(await ready()).toBeEnabled();
  cleanup();
  rendered = mount(detail(), async () => json({ code: 'unavailable' }, 503));
  expect(await within(rendered.section()).findByText('The request could not be confirmed. Your saved draft is retained.')).toHaveAttribute('role', 'status');
  expect(screen.queryByRole('button', { name: 'Review and approve publishing' })).not.toBeInTheDocument();
  for (const publication of ['preparing', 'needsAttention', 'complete'] as const) {
    cleanup(); const item = detail(); item.publication = publication; mount(item);
    expect(await screen.findByRole('combobox', { name: 'Visibility' })).toBeDisabled();
    expect(screen.queryByRole('button', { name: 'Review and approve publishing' })).not.toBeInTheDocument();
  }
  // A summary disabled by the page (unsaved edits, a conflict or running analysis) offers no write of its own.
  cleanup();
  const conflicts = [{ path: 'album.label', slotId: null, lookup: labelEntry('Lookup Label'), answer: null }], item = detail(); item.draft.album.label = labelEntry('Mine');
  mount(item, lookupResponse({ lookup: view({ state: 'stopped', outcome: null, issue: 'permissionLost', candidates: [candidate(1)], applied: applied({ conflicts }), needsAnswer: { tie: false, conflicts: ['album.label'] } }),
    summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }] }) }), { disabled: true });
  expect(await screen.findByRole('combobox', { name: 'Visibility' })).toBeDisabled();
  for (const name of ['Retry lookup', 'Analyze with Luna', 'Keep mine', 'Use lookup value', 'Apply ticked suggestions now']) expect(screen.getByRole('button', { name })).toBeDisabled();
  expect(screen.getByRole('checkbox', { name: /^Title/ })).toBeDisabled();
  expect(within(screen.getByRole('group', { name: 'Look up by name' })).getByRole('textbox')).toBeDisabled();
  // Publish includes unsaved edits, so only its own gate holds it.
  cleanup(); mount(detail(), lookupResponse(), { disabled: true });
  expect(await ready()).toBeEnabled();
});

test('the status names an unconfigured, replaced or none-applied lookup and counts stale files, and the Luna step needs analysis access, budget and an idle analysis', async () => {
  const cases: [Record<string, unknown>, string, string[]][] = [
    [{ state: 'unavailable', outcome: null, issue: 'notConfigured' }, 'Metadata lookup is not configured on this server. Edit the draft manually or analyze with Luna.', ['Analyze with Luna', 'Retry lookup']],
    [{ state: 'superseded', outcome: null, issue: 'fileSetChanged' }, 'This lookup was replaced because the files changed or the import closed.', ['Retry lookup', 'Analyze with Luna']],
    [{ candidates: [candidate(1)], groups: [group(1, 'Synthetic Album')], applied: applied({ candidateKey: null, releaseId: null, choice: 'none', basis: null }) }, 'No release is applied. Values from file tags are kept.', []]
  ];
  for (const [lookup, status, steps] of cases) {
    const { section } = mount(detail(), lookupResponse({ lookup: view(lookup) }));
    expect(await within(section()).findByText(status)).toHaveAttribute('role', 'status');
    expect(within(section()).queryAllByRole('button', { name: /^(Retry lookup|Analyze with Luna)$/ }).map(button => button.textContent)).toEqual(steps);
    cleanup();
  }
  // Where this server cannot run lookup at all, the summary says so with Luna as the next step, and offers neither a retry nor
  // the name box, before any run or after one that found it unconfigured.
  for (const lookup of [null, view({ state: 'unavailable', outcome: null, issue: 'notConfigured' })]) {
    const { section } = mount(detail(), lookupResponse({ lookup, summary: summary({ lookupAvailable: false }) }));
    expect(await within(section()).findByText('Metadata lookup is not configured on this server. Edit the draft manually or analyze with Luna.')).toHaveAttribute('role', 'status');
    expect(within(section()).queryAllByRole('button', { name: /^(Retry lookup|Analyze with Luna)$/ }).map(button => button.textContent)).toEqual(['Analyze with Luna']);
    expect(within(section()).queryByRole('group', { name: 'Look up by name' })).not.toBeInTheDocument();
    cleanup();
  }
  const noRelease = view({ outcome: 'noRelease', staleFiles: [slotTwo] }), luna = async () => screen.findByRole('button', { name: 'Analyze with Luna' });
  mount(detail(), lookupResponse({ lookup: noRelease }));
  expect(await luna()).toBeEnabled();
  expect(screen.getByText('Files changed since this lookup: 1. Their match evidence is out of date.')).toBeInTheDocument();
  const unavailable: [string, (item: ImportDetail) => unknown][] = [
    ['no analysis run left', () => undefined], ['analysis running', item => { item.analysis.state = 'running'; }], ['no analysis capability', item => { item.capabilities.analysis = false; }],
    ['an unknown provider outcome', item => { item.analysis.issue = 'providerOutcomeUnknown'; }], ['no analysis access', () => adminWorkspace.authorize(captureAccountOperation(viewer), true, false)]];
  for (const [why, change] of unavailable) {
    cleanup(); const item = detail(); change(item);
    mount(item, lookupResponse({ lookup: noRelease, summary: summary(why === 'no analysis run left' ? { analysis: { runs: 0, attempts: 20, daily: 200 } } : {}) }));
    expect(await luna(), why).toBeDisabled();
  }
});

test('answered conflicts fold with their answer, an artist mismatch is flagged only for a preselection applied in this run, and neither unsaved nor appended Album values are flagged as file tags', async () => {
  const item = detail(); item.draft.album.label = labelEntry('Mine'); item.draft.tracks[1].title = 'Mine';
  item.automaticPaths = ['album.title', 'album.releaseDate', `tracks.${slotId}.title`]; item.lookupPaths = [];
  const conflicts = [{ path: 'album.label', slotId: null, lookup: labelEntry('Lookup Label'), answer: 'mine' }, { path: `tracks.${slotTwo}.title`, slotId: slotTwo, lookup: 'Lookup Song', answer: 'lookup' }];
  const preselection = { candidateKey: key(1), basis: 'onlyMatchingGroup', artistMismatch: true };
  const changes = [{ path: 'album.title', base: '', value: 'Unsaved Title' }];
  mount(item, lookupResponse({ lookup: view({ run: 2, candidates: [candidate(1)], groups: [group(1, 'Synthetic Album')], preselection, applied: applied({ run: 2, choice: 'chosen', basis: 'chosen', conflicts }) }) }),
    { approval: { draft: { ...item.draft, album: { ...item.draft.album, title: 'Unsaved Title' } }, changes } });
  expect(await ready()).toBeEnabled();
  const fold = screen.getByText('Values that need no answer').closest('details')!;
  expect(within(fold).getByText('Lookup Label · Kept yours')).toBeInTheDocument(); expect(within(fold).getByText('Lookup Song · Lookup value used')).toBeInTheDocument();
  // The unsaved title is folded with its shown value; the release date and the first track's title rest on file tags.
  expect(within(fold).getByText('Unsaved Title')).toBeInTheDocument();
  expect(within(screen.getByRole('list', { name: 'Values to check' })).getAllByRole('listitem').map(entry => entry.textContent))
    .toEqual(['Release date: — · From file tags only', 'Track 1 · Title: — · From file tags only']);
  expect(screen.queryByRole('region', { name: 'Lookup values that differ from yours' })).not.toBeInTheDocument();
  cleanup();
  // The mismatch of a preselection applied in an earlier run is not this run's; an append flags no Album value.
  mount(item, lookupResponse({ summary: summary({ append: true }), lookup: view({ run: 2, preselection, applied: applied({ run: 1 }) }) }));
  await ready();
  expect(within(screen.getByRole('list', { name: 'Values to check' })).getAllByRole('listitem').map(entry => entry.textContent)).toEqual(['Track 1 · Title: — · From file tags only']);
  expect(screen.getByText('Untitled Album · Not applied')).toBeInTheDocument();
});

test('a suggestion whose value an unsaved change writes cannot be ticked, and the fold lists the shown tracks in approved order with decisions, cover and upload progress', async () => {
  const item = detail(); item.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }];
  item.selectedCoverSlotId = 'cover'; item.upload = { ready: 1, total: 2, available: true };
  const draft = { ...item.draft, tracks: [{ ...item.draft.tracks[0], title: 'Second Song', trackNumber: 2 }, { ...item.draft.tracks[1], title: 'First Song', trackNumber: 1 }] };
  const changes = [{ path: `tracks.${slotId}.trackNumber`, base: null, value: 2 }];
  mount(item, lookupResponse({ summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }, { id: 'd'.repeat(24), tick: 'ticked' }] }) }),
    { approval: { draft, changes }, uploads: { ...uploads, running: true } });
  const luna = await screen.findByRole('group', { name: 'Luna suggestions' });
  const number = within(luna).getByRole<HTMLInputElement>('checkbox', { name: /^Track 1 · Track number: 2 → 1/ });
  expect([number.checked, number.disabled, within(luna).getByRole<HTMLInputElement>('checkbox', { name: /^Title/ }).checked]).toEqual([false, true, true]);
  expect(within(luna).getByText('This value changed after analysis. Edit the draft manually or keep its current value.')).toBeInTheDocument();
  const fold = screen.getByText('Values that need no answer').closest('details')!;
  expect(within(within(fold).getByText('Disc and track order').closest('div')!).getAllByRole('listitem').map(entry => entry.textContent))
    .toEqual(['Disc 1 · Track 1 · First Song', 'Disc 1 · Track 2 · Second Song']);
  for (const text of ['Manually selected cover', 'Saved decisions: 1. The publication confirmation lists each new or reused record.', '1 of 2 files confirmed · Uploading'])
    expect(within(fold).getByText(text)).toBeInTheDocument();
  // The read is keyed by the saved revision and automatic writes, so a newer project reads its summary again.
  const access = { viewerId: viewer, epoch: 0, generation: 1 };
  expect(importSummaryQuery(access, { ...item, revision: 2 }).queryKey).not.toEqual(importSummaryQuery(access, item).queryKey);
  expect(importSummaryQuery(access, { ...item, valueRevision: 1 }).queryKey).not.toEqual(importSummaryQuery(access, item).queryKey);
});

test('the Analyze confirmation focuses Cancel, closes on Escape without starting anything, and cannot be confirmed while its budget is loading, failed or too small for one more run', async () => {
  const confirm = (response: () => Promise<Response>) => {
    vi.stubGlobal('fetch', vi.fn(response));
    const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
    const onConfirm = vi.fn(), onClose = vi.fn();
    render(<QueryClientProvider client={client}><ImportAnalysisConfirmation item={detail()} disabled={false} onConfirm={onConfirm} onClose={onClose} /></QueryClientProvider>);
    return { onConfirm, onClose, dialog: screen.getByRole('dialog', { name: 'Analyze with Luna?' }), start: () => screen.getByRole('button', { name: 'Start Luna analysis' }) };
  };
  const read = deferred<Response>();
  let opened = confirm(() => read.promise);
  await waitFor(() => expect(within(opened.dialog).getByRole('button', { name: 'Cancel' })).toHaveFocus());
  expect(within(opened.dialog).getByRole('status')).toHaveTextContent('Loading…'); expect(opened.start()).toBeDisabled();
  fireEvent.keyDown(document, { key: 'Escape' });
  expect(opened.onClose).toHaveBeenCalledOnce(); expect(opened.onConfirm).not.toHaveBeenCalled();
  cleanup();
  opened = confirm(async () => json({ code: 'unavailable' }, 503));
  expect(await within(opened.dialog).findByText('The request could not be confirmed. Your saved draft is retained.')).toBeInTheDocument();
  expect(opened.start()).toBeDisabled();
  // The fixture's two files need two calls: one for the Album and one per ten files.
  for (const [analysis, enabled] of [[{ runs: 0, attempts: 20, daily: 200 }, false], [{ runs: 1, attempts: 1, daily: 200 }, false], [{ runs: 1, attempts: 20, daily: 1 }, false], [{ runs: 1, attempts: 2, daily: 2 }, true]] as const) {
    cleanup(); opened = confirm(async () => json(lookupResponse({ summary: summary({ analysis }) })));
    await within(opened.dialog).findByText(`Left today for all imports: ${analysis.daily} AI calls.`);
    expect(opened.start().hasAttribute('disabled'), JSON.stringify(analysis)).toBe(!enabled);
  }
  fireEvent.click(opened.start()); expect(opened.onConfirm).toHaveBeenCalledOnce();
});
